class Solution:
    def maxMinimumCost(self, d: List[int]) -> int:
        # Sort. One server takes the lowest module alone and another takes a[i], with everything below a[i]
        # (except the lowest) on the third server: the adversary pays (a[i] - a[0]) + (a[i] - a[i-1]).
        # The mirror case puts the highest module alone. Try both for every i.
        a = sorted(d)
        n = len(a)
        best = 0
        for i in range(2, n):
            best = max(best, (a[i] - a[0]) + (a[i] - a[i - 1]))
        for i in range(n - 2):
            best = max(best, (a[n - 1] - a[i]) + (a[i + 1] - a[i]))
        return best

